testcase = int(input())
for case in range(testcase):
	n = int(input())
	arr = input()
	if arr[0] == '0' or arr[1] == '0' or arr[n] == '0':
		print('No')
	else:
		print('Yes')
		ans = [0]
		mex = []
		mex_n = []
		for i in range(1, n):
			if arr[i] == '1':
				mex.append(i)
			else:
				mex_n.append(i)
		ans += mex_n + mex
		for i in ans:
			print(i, end=' ')
		print()
